__global__ void lookup(const uint8_t*p,const float*s,const uint32_t*ids,float*out,int dims,int stride,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n*dims){uint32_t id=ids[i/dims];out[i]=s[id]*tao::ternary::at_unchecked(p+size_t(id)*stride,i%dims);}}
